/** Look up an IML event by class + event code. */
export function getImlEvent(classCode, eventCode) {
  const cls = Number(classCode).toString(16).padStart(4, "0");
  const ev = Number(eventCode).toString(16).padStart(4, "0");
  return IML_EVENTS.find((e) =>
    e.class.toString(16).padStart(4, "0") === cls &&
    e.event.toString(16).padStart(4, "0") === ev
  ) ?? null;
}
